import numpy as np, json
def apply_ffn_prune(m, layers, W, base, save_edit, set_structure, WORK, fold=True, imp_file='ffn_imp.npz', extra_keep=None):
    F=np.load(WORK/imp_file)
    keep={}
    for L in layers:
        imp=F[f'imp{L}']
        if np.all(imp==0) or np.isnan(imp).any():
            k=list(range(m))
        else:
            k=sorted(np.argsort(-imp)[:m].tolist())
        keep[L]=k
        if fold and L<=10:
            E=F[f'E{L}']; Wout=W(f'bert.encoder.layer.{L}.output.dense.weight')
            drop=np.setdiff1d(np.arange(3072), k)
            b0=base(f'bert.encoder.layer.{L}.output.dense.bias')
            save_edit(f'bert.encoder.layer.{L}.output.dense.bias', (b0 + Wout[:,drop]@E[drop]).astype(np.float32))
    return set_structure(layers=layers, ffn_keep=keep)
'''
